 } elseif($acao==='excluir') { $nomeExcluir=trim($_POST['nome_excluir']??''); if($nomeExcluir===$uNome=($_SESSION['sisbank_user']['nome']??'')) $erro='Você não pode excluir o usuário que está utilizando.'; else { $stmt=mysqli_prepare($conexao,'DELETE FROM tbgerentes WHERE nome=?');mysqli_stmt_bind_param($stmt,'s',$nomeExcluir);mysqli_stmt_execute($stmt);$_SESSION['mensagem']='Operação de exclusão concluída.';redirecionar('gerentes.php'); } }
